<?php
$page_title='รายละเอียดคำสั่งซื้อ';require_once __DIR__.'/includes/auth_check.php';requireLogin();require_once __DIR__.'/config/database.php';
$db=(new Database())->getConnection();$id=(int)($_GET['id']??0);$order=null;$items=[];$history=[];
if($db&&$id){$s=$db->prepare('SELECT * FROM orders WHERE id=? AND user_id=?');$s->execute([$id,(int)$_SESSION['user_id']]);$order=$s->fetch();if($order){$s=$db->prepare('SELECT * FROM order_items WHERE order_id=?');$s->execute([$id]);$items=$s->fetchAll();try{$s=$db->prepare('SELECT * FROM order_status_history WHERE order_id=? ORDER BY created_at DESC,id DESC');$s->execute([$id]);$history=$s->fetchAll();}catch(Throwable $ignored){}}}
if(!$order){header('Location: '.BASE_URL.'my-orders.php');exit;}$labels=['pending'=>'รับคำสั่งซื้อแล้ว','processing'=>'กำลังจัดเตรียมสินค้า','shipped'=>'ส่งสินค้าแล้ว','completed'=>'ส่งมอบสำเร็จ','cancelled'=>'ยกเลิกคำสั่งซื้อ','paid'=>'ชำระเงินแล้ว','cod_pending'=>'รอชำระปลายทาง'];require __DIR__.'/includes/header.php';
?><div class="container" style="max-width:920px;padding:34px 16px 70px"><a href="<?php echo BASE_URL;?>my-orders.php">← กลับไปประวัติคำสั่งซื้อ</a><section style="background:#fff;padding:28px;border:1px solid var(--border-color);margin-top:18px"><div style="display:flex;justify-content:space-between;gap:18px;flex-wrap:wrap"><div><p class="eyebrow">ORDER DETAIL</p><h1><?php echo e($order['order_no']);?></h1><p>สั่งซื้อวันที่ <?php echo date('d/m/Y H:i',strtotime($order['created_at']));?></p></div><div><a class="btn btn-outline" href="<?php echo BASE_URL;?>receipt.php?id=<?php echo $id;?>"><i class="fa-solid fa-file-invoice"></i> เอกสารคำสั่งซื้อ</a> <a class="btn btn-outline" href="<?php echo BASE_URL;?>support.php"><i class="fa-regular fa-comments"></i> ขอความช่วยเหลือ</a></div></div><hr style="margin:20px 0;border:0;border-top:1px solid var(--border-color)"><h2>สถานะล่าสุด: <?php echo e($labels[$order['order_status']]??$order['order_status']);?></h2><?php if($history):?><div style="border-left:3px solid #dce9e2;margin:18px 8px;padding-left:22px"><?php foreach($history as $h):?><article style="position:relative;margin-bottom:18px"><span style="position:absolute;width:13px;height:13px;border-radius:50%;background:#176048;left:-30px;top:5px"></span><strong><?php echo e($labels[$h['order_status']]??$h['order_status']);?></strong><p style="margin:3px 0"><?php echo e($h['note']??'');?></p><small><?php echo date('d/m/Y H:i',strtotime($h['created_at']));?></small></article><?php endforeach;?></div><?php endif;?><h2 style="margin-top:26px">รายการสินค้า</h2><?php foreach($items as $item):?><div style="display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid var(--border-color)"><span><?php echo e($item['product_name']);?> × <?php echo (int)$item['quantity'];?></span><strong><?php echo formatCurrency($item['subtotal']);?></strong></div><?php endforeach;?><div style="display:flex;justify-content:space-between;font-size:1.2rem;padding-top:16px"><strong>ยอดรวม</strong><strong><?php echo formatCurrency($order['total_amount']);?></strong></div><h3 style="margin-top:24px">ข้อมูลจัดส่ง</h3><p><?php echo e($order['shipping_name']);?> · <?php echo e($order['shipping_phone']);?><br><?php echo nl2br(e($order['shipping_address']));?></p><?php if($order['payment_method']==='promptpay'&&$order['payment_status']==='pending'):?><a class="btn btn-primary" href="<?php echo BASE_URL;?>order-success.php?order_id=<?php echo $id;?>">ไปหน้าชำระเงิน</a><?php endif;?></section></div><?php require __DIR__.'/includes/footer.php';?>
